+++ 
@@ -1,1 +1,10 @@
-firestore.rules
\ No newline at end of file
+rules_version = '2';
+
+service cloud.firestore {
+  match /databases/{database}/documents {
+    // Allow all authenticated users to read/write everything
+    match /{document=**} {
+      allow read, write: if request.auth != null;
+    }
+  }
+}
